  "implementation": "def solve(case):
    import json
    nodes = set(case['nodes'])
    core_dist = case['core_distance']
    distances = case['distances']

    class UnionFind:
        def __init__(self, items):
            self.parent = {item: item for item in items}
            self.rank = {item: 0 for item in items}
        def find(self, x):
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x
        def union(self, x, y):
            rx, ry = self.find(x), self.find(y)
            if rx == ry:
                return False
            if self.rank[rx] < self.rank[ry]:
                self.parent[rx] = ry
            elif self.rank[rx] > self.rank[ry]:
                self.parent[ry] = rx
            else:
                self.parent[ry] = rx
                self.rank[rx] += 1
            return True

    edges = []
    for a, b, d in distances:
        if a > b:
            a, b = b, a
        w = max(core_dist[a], core_dist[b], d)
        edges.append((w, a, b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    uf = UnionFind(nodes)
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if uf.union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph is disconnected, cannot compute MST')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
